/// <summary>
/// 106341-Customber Bank validation for DD
/// </summary>
public class METCustTableEventHandler
{   
}

Method.Source:
/// <summary>
///on modified , need to validate
/// </summary>
/// <param name="sender">table</param>
/// <param name="e">event</param>
[DataEventHandler(tableStr(CustTable), DataEventType::ModifiedFieldValue)]
public static void CustTable_onModifiedFieldValue(Common sender, DataEventArgs e)
{
    CustTable CustTable = sender;
    ModifyFieldValueEventArgs event = e as ModifyFieldValueEventArgs;
    CustBankAccount bankaccSetup;
    select firstonly bankaccsetup where bankaccSetup.CustAccount==custTable.AccountNum
       && bankaccSetup.AccountNum && bankaccSetup.RegistrationNum;
    if (event && event.parmFieldName())
    {
        switch (event.parmFieldName())
        {
            case fieldStr(CustTable, PaymMode):
                if(CustTable.PaymMode == METConstants::DD && !custTable.BankAccount && !bankaccSetup)
                {
                    CustTable.PaymMode =custTable.orig().(fieldName2Id(CustTable.TableId,event.parmFieldName()));//METConstants::None;
                    if(CustTable.PaymMode == METConstants::DD)
                    {
                        CustTable.PaymMode =   METConstants::None;
                    }
                    warning("@MET:METCustValidation6");
                    break;
                }
            case fieldStr(CustTable, bankaccount):
                if(CustTable.PaymMode == METConstants::DD && !custTable.BankAccount && !bankaccSetup)
                {
                    CustTable.PaymMode =custTable.orig().(fieldName2Id(CustTable.TableId,event.parmFieldName()));//METConstants::None;
                    if(CustTable.PaymMode == METConstants::DD)
                    {
                        CustTable.PaymMode =  '';
                    }
                    warning("@MET:METCustValidation6");
                    break;
                }
                else  if(CustTable.PaymMode == METConstants::DD && custTable.BankAccount && !bankaccSetup)
                {
                    CustTable.PaymMode =custTable.orig().(fieldName2Id(CustTable.TableId,event.parmFieldName()));//METConstants::None;
                    if(CustTable.PaymMode == METConstants::DD)
                    {
                        CustTable.PaymMode = '';
                        custTable.BankAccount='';
                    }
                    warning("@MET:METCustValidation6");
                    break;
                }
        }
    }
}
